<div class="container">
    <header>
        <h1>Recipe Launch Board</h1>
    </header>

    <!-- Section 1: Recipe Details -->
    <div class="card">
        <h2>Recipe Details</h2>
        <div class="input-group">
            <label for="recipeName">Recipe Name</label>
            <input type="text" id="recipeName" placeholder="e.g., Lemon Blueberry Loaf">
        </div>
        <div class="input-group">
            <label for="recipeBody">Recipe/Method Highlights</label>
            <textarea id="recipeBody" placeholder="Paste ingredients or key steps here..."></textarea>
        </div>
    </div>

    <!-- Section 2: Asset Checklist -->
    <div class="card">
        <h2>Promo Assets Needed</h2>
        <div class="checkbox-group">
            <label class="checkbox-label"><input type="checkbox" id="assetTitle" class="tracker"> Title Setup</label>
            <label class="checkbox-label"><input type="checkbox" id="assetCaption" class="tracker"> Caption Drafted</label>
            <label class="checkbox-label"><input type="checkbox" id="assetHashtags" class="tracker"> Hashtags Researched</label>
            <label class="checkbox-label"><input type="checkbox" id="assetAllergens" class="tracker"> Allergen Notes Flagged</label>
            <label class="checkbox-label"><input type="checkbox" id="assetChannels" class="tracker"> Channel Formats Checked</label>
        </div>
    </div>

    <!-- Section 3: Readiness & Output -->
    <div class="card">
        <h2>Readiness Status</h2>
        <div id="statusBadge" class="status-badge status-pending">Pending Assets</div>
        <div id="issuesList"></div>

        <button class="btn" onclick="copyChecklist()">Copy Launch Checklist</button>
        <div id="outputPreview" class="output-box"></div>
    </div>
</div>

<script>
    const inputs = document.querySelectorAll('#recipeName, #recipeBody, .tracker');

    inputs.forEach(input => {
        input.addEventListener('input', updateBoard);
    });

    function updateBoard() {
        const name = document.getElementById('recipeName').value.trim();
        const body = document.getElementById('recipeBody').value.trim();

        const assets = {
            'Title': document.getElementById('assetTitle').checked,
            'Caption': document.getElementById('assetCaption').checked,
            'Hashtags': document.getElementById('assetHashtags').checked,
            'Allergen Notes': document.getElementById('assetAllergens').checked,
            'Channel Checks': document.getElementById('assetChannels').checked
        };

        const issuesList = document.getElementById('issuesList');
        const statusBadge = document.getElementById('statusBadge');
        const outputPreview = document.getElementById('outputPreview');

        let issues = [];
        if (!name) issues.push("Missing recipe name");
        if (!body) issues.push("Missing recipe content");

        Object.keys(assets).forEach(asset => {
            if (!assets[asset]) {
                issues.push(`Missing ${asset}`);
            }
        });

        // Update Issues Display
        issuesList.innerHTML = '';
        if (issues.length > 0) {
            statusBadge.textContent = 'Pending Assets';
            statusBadge.className = 'status-badge status-pending';
            issues.forEach(issue => {
                const item = document.createElement('div');
                item.className = 'issue-item';
                item.innerHTML = `⚠️ ${issue}`;
                issuesList.appendChild(item);
            });
        } else {
            statusBadge.textContent = 'Ready for Launch';
            statusBadge.className = 'status-badge status-ready';
            issuesList.innerHTML = '<div style="color: var(--success); font-size: 0.9rem;">✨ Everything looks good to go!</div>';
        }

        // Generate Checklist Text
        let checklistText = `LAUNCH CHECKLIST: ${name || 'Untitled Recipe'}\n`;
        checklistText += `==================================\n\n`;
        checklistText += `[${name ? 'X' : ' '}] Recipe Name Confirmed\n`;
        checklistText += `[${body ? 'X' : ' '}] Recipe Content Ready\n`;
        checklistText += `[${assets['Title'] ? 'X' : ' '}] Title Setup\n`;
        checklistText += `[${assets['Caption'] ? 'X' : ' '}] Caption Drafted\n`;
        checklistText += `[${assets['Hashtags'] ? 'X' : ' '}] Hashtags Researched\n`;
        checklistText += `[${assets['Allergen Notes'] ? 'X' : ' '}] Allergen Notes Flagged\n`;
        checklistText += `[${assets['Channel Checks'] ? 'X' : ' '}] Channel Formats Checked\n\n`;
        checklistText += `Status: ${issues.length === 0 ? 'READY' : 'INCOMPLETE'}`;

        outputPreview.textContent = checklistText;
    }

    function copyChecklist() {
        const text = document.getElementById('outputPreview').textContent;
        navigator.clipboard.writeText(text).then(() => {
            const btn = document.querySelector('.btn');
            const originalText = btn.textContent;
            btn.textContent = 'Copied!';
            btn.style.background = 'var(--success)';
            setTimeout(() => {
                btn.textContent = originalText;
                btn.style.background = 'var(--accent)';
            }, 1500);
        });
    }

    // Initial run to populate empty fields state
    updateBoard();
</script>

</body>
